--
-- Name: idea_embedding_pairs(uuid, double precision, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.idea_embedding_pairs(tenant uuid, threshold double precision, max_pairs integer) RETURNS TABLE(a_id uuid, b_id uuid, similarity double precision)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
        SELECT e1.idea_id AS a_id,
               e2.idea_id AS b_id,
               (1 - (e1.embedding <=> e2.embedding))::float AS similarity
          FROM idea_embeddings e1
          JOIN idea_embeddings e2
            ON e2.tenant_id = e1.tenant_id
           AND e2.idea_id  > e1.idea_id
         WHERE e1.tenant_id = tenant
           AND 1 - (e1.embedding <=> e2.embedding) >= threshold
         ORDER BY similarity DESC
         LIMIT max_pairs;
END;
$$;


--
-- Name: match_idea_embeddings(uuid, uuid, text, integer, double precision); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.match_idea_embeddings(tenant uuid, exclude_idea uuid, query text, k integer, threshold double precision) RETURNS TABLE(id uuid, title text, description text, stage text, category text, similarity double precision)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
        SELECT i.id,
               i.title,
               i.description,
               i.stage::text,
               i.category,
               (1 - (e.embedding <=> query::vector))::float AS similarity
          FROM idea_embeddings e
          JOIN ideas i ON i.id = e.idea_id
         WHERE e.tenant_id = tenant
           AND e.idea_id <> exclude_idea
           AND i.stage NOT IN ('DRAFT', 'REJECTED', 'ARCHIVED')
           AND 1 - (e.embedding <=> query::vector) >= threshold
         ORDER BY e.embedding <=> query::vector
         LIMIT k;
END;
$$;


--
-- Name: upsert_idea_embedding(uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.upsert_idea_embedding(idea uuid, tenant uuid, embedding text, model text) RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN
    INSERT INTO idea_embeddings (idea_id, tenant_id, embedding, model)
    VALUES (idea, tenant, embedding::vector, model)
    ON CONFLICT (idea_id) DO UPDATE
      SET embedding = EXCLUDED.embedding,
          model     = EXCLUDED.model,
          tenant_id = EXCLUDED.tenant_id;
END;
$$;


